// RunStateSuite applies the checks of State, and the checks that opts add,
// to a fresh subject of newSubject for each check.
func RunStateSuite[T StateMethods](t *testing.T, newSubject func() T, opts ...StateOption) {
	t.Helper()
	RunStateSuiteFromHandle(t, func(*StateHandle) T { return newSubject() }, opts...)
}

// RunStateSuiteFromHandle applies the same checks to a subject that
// newSubject builds from the handle of each check.
func RunStateSuiteFromHandle[T StateMethods](t *testing.T, newSubject func(h *StateHandle) T, opts ...StateOption) {
	t.Helper()
	conform.Run(t, StateSuite(), stateSubjects(newSubject), opts...)
}

// FuzzStateSuite registers on f the fuzz target of the property checks of
// callable, on a subject that newSubject builds from the handle of each
// case.
func FuzzStateSuite[T StateMethods](
	f *testing.F,
	callable conform.Callable[StateMethods],
	newSubject func(h *StateHandle) T,
	opts ...StateOption,
) {
	f.Helper()
	conform.Fuzz(f, StateSuite(), callable, stateSubjects(newSubject), opts...)
}

// RunStateBudgets applies the allocation ceilings of State and its checks
// that count allocations, and the ceilings and the checks that opts add,
// to a fresh subject of newSubject for each case.
func RunStateBudgets[T StateMethods](t *testing.T, newSubject func(h *StateHandle) T, opts ...StateOption) {
	t.Helper()
	conform.RunBudgets(t, StateSuite(), stateSubjects(newSubject), opts...)
}

// BenchStateSuite measures callable on a subject of newSubject, under the
// ceilings of its budget.
func BenchStateSuite[T StateMethods](
	b conform.B,
	callable conform.Callable[StateMethods],
	newSubject func(h *StateHandle) T,
	opts ...StateOption,
) {
	b.Helper()
	conform.Bench(b, StateSuite(), callable, stateSubjects(newSubject), opts...)
}

// stateSubjects returns the factory of the subjects of State that calls
// newSubject with the handle of each check.
func stateSubjects[T StateMethods](newSubject func(h *StateHandle) T) func(h *StateHandle) StateMethods {
	return func(h *StateHandle) StateMethods { return newSubject(h) }
}

